@layer hj.components {
  /* Customise: --hj-link-color · --hj-link-underline-offset */
  .hj-link {
    --_c: var(--hj-link-color, var(--hj-accent-text));
    color: var(--_c);
    font-weight: 500;
    text-decoration-line: underline;
    text-decoration-thickness: 1px;
    text-underline-offset: var(--hj-link-underline-offset, 0.22em);
    text-decoration-color: color-mix(in srgb, var(--_c) 40%, transparent);
    border-radius: 3px;
    cursor: pointer;
    transition:
      text-decoration-color var(--hj-dur-fast) var(--hj-ease-out),
      color var(--hj-dur-fast) var(--hj-ease-out),
      opacity var(--hj-dur-fast) var(--hj-ease-out);
  }
  .hj-link:hover {
    text-decoration-color: var(--_c);
  }
  .hj-link:active {
    opacity: var(--hj-press-opacity);
    transition-duration: 70ms;
  }
  .hj-link[data-tone='fg'] {
    --_c: var(--hj-link-color, var(--hj-fg));
  }
  .hj-link[data-tone='dim'] {
    --_c: var(--hj-link-color, var(--hj-fg-dim));
  }
  .hj-link[data-underline='hover'] {
    text-decoration-color: transparent;
  }
  .hj-link[data-underline='hover']:hover {
    text-decoration-color: color-mix(in srgb, var(--_c) 60%, transparent);
  }

  .hj-link-glyph {
    display: inline-flex;
    margin-left: 0.15em;
    font-size: 0.85em;
    vertical-align: -0.05em;
    transition: transform var(--hj-dur-snappy) var(--hj-ease-snappy);
  }
  .hj-link:hover .hj-link-glyph {
    transform: translate(calc(1.5px * var(--hj-travel)), calc(-1.5px * var(--hj-travel)));
  }
  .hj-link-note {
    position: absolute;
    width: 1px;
    height: 1px;
    margin: -1px;
    overflow: hidden;
    clip: rect(0 0 0 0);
    white-space: nowrap;
  }
}

'use client';
import { useRender } from '@base-ui/react/use-render';
import * as React from 'react';

import { useHanjiConfig } from '../../system/config.tsx';
import { cls, flag, withDefaults } from '../../system/slot.ts';

/** Props hanji adds to `<a>`. */
export interface LinkOwnProps {
  /** accent for links in running text; fg for quiet links in chrome; dim for footnotes. */
  tone?: 'accent' | 'fg' | 'dim';
  /** always = underlined at rest (running text); hover = underline appears on hover (chrome). */
  underline?: 'always' | 'hover';
  /**
   * Opens in a new tab: adds target and rel, a ↗ glyph, and a visually hidden note for screen
   * readers.
   */
  external?: boolean;
  /** The hidden note read after an external link. @default strings.opensInNewTab */
  externalLabel?: string;
  /** Render a router link (e.g. `render={<RouterLink to="/library" />}`). */
  render?: useRender.RenderProp;
}

export interface LinkProps extends LinkOwnProps, Omit<React.ComponentProps<'a'>, 'className'> {
  className?: string;
}

function ArrowUpRight(): React.JSX.Element {
  return (
    <svg
      viewBox="0 0 24 24"
      width="1em"
      height="1em"
      fill="none"
      stroke="currentColor"
      strokeWidth={1.75}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      focusable="false"
    >
      <path d="M7 17 17 7M8 7h9v9" />
    </svg>
  );
}

/**
 * A link: goes somewhere. Underline offset and thickness set for reading; the underline slides
 * its colour, never its position.
 *
 * @example
 * <Link href="/terms">terms of service</Link>
 * <Link href="https://help.example.com" external>Help centre</Link>
 */
export function Link(props: LinkProps): React.ReactElement {
  const config = useHanjiConfig();
  const {
    tone = 'accent',
    underline = 'always',
    external = false,
    externalLabel = config.strings.opensInNewTab,
    render,
    className,
    children,
    target,
    rel,
    ...rest
  } = withDefaults(config, 'Link', props);
  const styled = !config.unstyled;
  return useRender({
    render,
    defaultTagName: 'a',
    props: {
      ...rest,
      target: external ? (target ?? '_blank') : target,
      rel: external ? (rel ?? 'noopener noreferrer') : rel,
      'data-tone': tone,
      'data-underline': underline,
      'data-external': flag(external),
      className: cls(config, 'Link', 'hj-link', className) as string | undefined,
      children: external ? (
        <>
          {children}
          <span className={styled ? 'hj-link-glyph' : undefined}>
            <ArrowUpRight />
          </span>
          <span className={styled ? 'hj-link-note' : undefined}>{` (${externalLabel})`}</span>
        </>
      ) : (
        children
      ),
    },
  });
}
